mapper.update:
UPDATE t_feedback_source
SET fault_occurred_at = CASE id
    WHEN #{update.sourceId} THEN #{update.occurredAt}
    ELSE fault_occurred_at END,
    fault_time_raw = CASE id
    WHEN #{update.sourceId} THEN #{update.raw}
    ELSE fault_time_raw END,
    fault_time_precision = CASE id
    WHEN #{update.sourceId} THEN #{update.precision}
    ELSE fault_time_precision END,
    fault_time_source = CASE id
    WHEN #{update.sourceId} THEN #{update.source}
    ELSE fault_time_source END,
    fault_time_resolution = CASE id
    WHEN #{update.sourceId} THEN #{update.resolution}
    ELSE fault_time_resolution END,
    updated_at = NOW(3)
WHERE fault_time_resolution = 'PENDING' AND id IN
#{update.sourceId}
